contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry performing the property test
    function run(uint dummy) public payable {
        // dummy parameter to range over inputs (unused)
        uint beforeC = address(c).balance;

        bool reverted;
        // state-changing call must be a top-level statement
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // GENERAL RULE: for any input, either the call reverted or C's balance is zero afterwards
        assert(reverted || address(c).balance == 0);
    }

    // allow receiving Ether when selfdestruct sends funds here
    receive() external payable {}
}

